    'Приватность: данные (ФИО инженера, заказчик, подпись, координаты GPS, фото) хранятся локально в IndexedDB и localStorage вашего браузера и никуда не передаются. При использовании чужого устройства очищайте данные кнопкой «Сброс».':'Գաղտնիություն. տվյալները (ինժեների անունը, պատվիրատուն, ստորագրությունը, GPS կոորդինատները, լուսանկարը) պահվում են ձեր բրաուզերի IndexedDB-ում և localStorage-ում և ոչ մի տեղ չեն փոխանցվում: Ուրիշի սարք օգտագործելիս մաքրեք տվյալները «Վերականգնել» կոճակով:',
